package Question7;

class Commission extends Payment { protected double commissionRate; protected double commissionAmount; public Commission(int id, String agencyName, String location, String phoneNumber, String agentName, String emailAgent, String licenseNumber, String propertyCode, String propertyType, double price, String sellerName, String contactNumber, String buyerName, String email, String agreementDate, String terms, double paymentAmount, String paymentDate, double commissionRate){ super(id, agencyName, location, phoneNumber, agentName, emailAgent, licenseNumber, propertyCode, propertyType, price, sellerName, contactNumber, buyerName, email, agreementDate, terms, paymentAmount, paymentDate); setCommissionRate(commissionRate); } public void setCommissionRate(double r){ this.commissionRate = Math.max(0.0, r); this.commissionAmount = (this.price * this.commissionRate) / 100.0; } }
